const routes=[
 {id:'qa',n:'01',icon:'✓',title:'QA & Testing',desc:'Estrategia, defectos y calidad.',color:'#d6ff43'},
 {id:'playwright',n:'02',icon:'⌘',title:'Playwright',desc:'E2E, fixtures y automatización.',color:'#65d9ff'},
 {id:'engineering',n:'03',icon:'{}',title:'Engineering',desc:'APIs, datos, CI/CD y web.',color:'#b99cff'},
 {id:'ai',n:'04',icon:'✦',title:'AI Automation',desc:'Agentes, MCP y orquestación.',color:'#ffb66d'},
 {id:'ops',n:'05',icon:'◉',title:'Operations',desc:'Observabilidad, IoT y fiabilidad.',color:'#ff89b5'}
];
const questions=[
 {r:'qa',q:'¿Cuál es el objetivo principal de una prueba de regresión?',a:['Encontrar únicamente defectos nuevos','Confirmar que cambios recientes no rompieron funcionalidad existente','Medir el rendimiento bajo carga','Validar solo la interfaz visual'],c:1,e:'La regresión protege comportamiento que ya funcionaba. Después de un cambio, se ejecutan pruebas relevantes sobre funcionalidades existentes para detectar efectos secundarios antes de entregar.'},
 {r:'qa',q:'En una prueba exploratoria, ¿qué práctica genera mayor valor?',a:['Seguir un script rígido sin desviarse','Automatizar todos los casos antes de probar','Investigar guiado por una misión, observando riesgos y adaptando el siguiente paso','Probar únicamente el camino feliz'],c:2,e:'La exploración combina aprendizaje, diseño y ejecución. Una misión da foco, pero la persona tester adapta sus pruebas según la evidencia y los riesgos que va descubriendo.'},
 {r:'qa',q:'¿Qué aporta la trazabilidad entre requisitos, casos de prueba y defectos?',a:['Más líneas de código de pruebas','Visibilidad de cobertura e impacto de cada requisito','Una sustitución completa de las pruebas manuales','Menor necesidad de comunicar riesgos'],c:1,e:'La trazabilidad permite saber qué requisitos fueron verificados, qué evidencia existe y qué defectos los afectan. Es clave para reportar cobertura y evaluar el impacto de cambios.'},
 {r:'playwright',q:'¿Por qué conviene usar locators basados en role o label en Playwright?',a:['Porque siempre son más cortos','Porque reflejan cómo usuarios y tecnologías asistivas perciben la UI','Porque evitan esperar elementos','Porque solo funcionan en Chromium'],c:1,e:'Los locators semánticos, como getByRole o getByLabel, son más resistentes a cambios de estructura y promueven una interfaz accesible. También expresan claramente la intención del test.'},
 {r:'playwright',q:'¿Qué problema resuelven las fixtures de Playwright?',a:['Definen colores de la aplicación','Encapsulan setup, datos y dependencias reutilizables para los tests','Reemplazan el control de versiones','Solo sirven para hacer mocks de red'],c:1,e:'Las fixtures preparan y entregan recursos a los tests de forma controlada: por ejemplo, una sesión autenticada, un cliente API o datos temporales. Esto reduce duplicación y mejora el aislamiento.'},
 {r:'playwright',q:'¿Cuándo es apropiado interceptar una petición de red en un test E2E?',a:['Siempre, para que ninguna prueba use backend','Cuando se necesita controlar una dependencia externa, simular un borde o aislar un escenario','Solo cuando falla un selector','Para reemplazar assertions'],c:1,e:'La intercepción permite escenarios deterministas, como errores de un proveedor o respuestas límite. Debe usarse con intención: los flujos críticos también necesitan cobertura integrada contra servicios reales o contratos.'},
 {r:'engineering',q:'¿Qué valida un API contract test además de un status 200?',a:['El tamaño de la ventana del navegador','Que request y response respeten el esquema y las expectativas acordadas','Que el usuario conozca SQL','Que la API tenga una interfaz bonita'],c:1,e:'Un contrato verifica la forma y las reglas de intercambio: campos requeridos, tipos, formatos y códigos esperados. Evita que un cambio aparentemente válido rompa a consumidores del servicio.'},
 {r:'engineering',q:'¿Qué beneficio ofrece ejecutar la suite de tests en GitHub Actions?',a:['Hace innecesario revisar pull requests','Da feedback repetible y temprano sobre cada cambio','Elimina todos los bugs de producción','Reemplaza por completo las pruebas locales'],c:1,e:'La integración continua ejecuta verificaciones de manera consistente en cada cambio. Así los problemas aparecen cerca de su origen y el equipo mantiene una señal compartida de calidad.'},
 {r:'engineering',q:'¿Para qué se usan variables de entorno en una aplicación?',a:['Para guardar secretos en el repositorio','Para separar configuración y credenciales del código, según cada ambiente','Para reemplazar la validación de inputs','Para mejorar selectores de UI'],c:1,e:'Las variables de entorno permiten que el mismo código se configure distinto en desarrollo, prueba y producción. Los secretos deben gestionarse de forma segura y nunca quedar hardcodeados o versionados.'},
 {r:'ai',q:'En un sistema con LLM y tool calling, ¿qué reduce mejor el riesgo de una acción inválida?',a:['Dejar que el modelo invente los parámetros','Validar parámetros con un esquema estructurado antes de ejecutar la herramienta','Usar prompts cada vez más largos','Ocultar la respuesta final al usuario'],c:1,e:'Los esquemas (por ejemplo, JSON Schema o Pydantic) convierten la salida del modelo en una interfaz verificable. La aplicación valida tipos, campos y límites antes de invocar una acción externa.'},
 {r:'ai',q:'¿Qué rol cumple MCP en una solución agentic?',a:['Es un modelo de lenguaje nuevo','Estandariza cómo un cliente descubre y usa contexto, herramientas y recursos de un servidor','Es una base de datos vectorial','Sustituye los permisos de seguridad'],c:1,e:'Model Context Protocol define una forma común de conectar modelos o clientes con herramientas y contexto. Facilita integraciones explícitas, descubribles y con fronteras claras entre cliente y servidor.'},
 {r:'ai',q:'¿Cuándo aporta RAG a una aplicación con LLM?',a:['Cuando se necesita recuperar fuentes relevantes y actuales para fundamentar una respuesta','Cuando el modelo debe dibujar una interfaz','Solo para entrenar un modelo desde cero','Para evitar toda evaluación humana'],c:0,e:'Retrieval-Augmented Generation recupera documentos relevantes en tiempo de consulta y los aporta como contexto. Esto mejora la conexión con conocimiento específico sin tener que reentrenar el modelo.'},
 {r:'ops',q:'¿Qué diferencia a una alerta útil de una alerta ruidosa?',a:['Una alerta útil se dispara por cualquier log','Una alerta útil es accionable, ligada a impacto y tiene una respuesta definida','Una alerta útil siempre se envía por más de cinco canales','Una alerta útil evita guardar métricas'],c:1,e:'Una buena alerta avisa de un problema que alguien puede investigar o mitigar. Debe basarse en señales de impacto y enlazar a un runbook o contexto para evitar fatiga de alertas.'},
 {r:'ops',q:'¿Por qué MQTT es frecuente en escenarios de IoT y Home Assistant?',a:['Porque requiere video en alta resolución','Porque es un protocolo liviano pub/sub apropiado para dispositivos y redes variables','Porque reemplaza una base de datos relacional','Porque solo funciona sin sensores'],c:1,e:'MQTT reduce acoplamiento: sensores publican estados y los consumidores se suscriben a tópicos. Su bajo costo y el patrón pub/sub lo vuelven práctico para automatización doméstica y telemetría.'},
 {r:'ops',q:'¿Cuál es el primer objetivo de un análisis de causa raíz tras un incidente?',a:['Buscar una persona responsable','Restaurar y entender el sistema para prevenir recurrencias mediante evidencia','Eliminar los registros para simplificar','Agregar más alertas sin investigar'],c:1,e:'Un RCA efectivo es sistémico y libre de culpas. Reúne evidencia, identifica condiciones contribuyentes y termina en mejoras verificables: automatizaciones, controles, documentación o cambios de diseño.'}
];
let active=[],index=0,score=0,answered=false,currentRoute='';const panel=document.querySelector('#questionPanel');
const grid=document.querySelector('#routeGrid');routes.forEach(r=>{const el=document.createElement('article');el.className='route';el.style.setProperty('--route',r.color);el.innerHTML=`<span class="route-num">${r.n} / MÓDULO</span><span class="route-icon">${r.icon}</span><h3>${r.title}</h3><p>${r.desc}</p><button>INICIAR RUTA →</button>`;el.onclick=()=>start(r.id);grid.append(el)});
document.querySelector('#startAll').onclick=()=>start('all');document.querySelector('#restart').onclick=()=>start(currentRoute);
function start(route){currentRoute=route;active=questions.filter(x=>route==='all'||x.r===route).sort(()=>Math.random()-.5);index=0;score=0;document.querySelector('#restart').hidden=false;document.querySelector('#quizTitle').textContent=route==='all'?'Simulación completa':routes.find(x=>x.id===route).title;document.querySelector('#quizHint').textContent=`${active.length} preguntas seleccionadas para esta sesión.`;document.querySelector('#simulador').scrollIntoView({behavior:'smooth',block:'center'});render()}
function render(){answered=false;const q=active[index];const letter=['A','B','C','D'];panel.innerHTML=`<div class="question"><div class="question-top">PREGUNTA ${index+1} DE ${active.length} · ${routes.find(x=>x.id===q.r).title.toUpperCase()}</div><h3>${q.q}</h3><div class="options">${q.a.map((x,i)=>`<button class="option" data-i="${i}"><strong>${letter[i]}</strong>${x}</button>`).join('')}</div><div id="feedback"></div></div>`;panel.querySelectorAll('.option').forEach(b=>b.onclick=()=>answer(+b.dataset.i));updateProgress()}
function answer(choice){if(answered)return;answered=true;const q=active[index],opts=panel.querySelectorAll('.option');opts.forEach((b,i)=>{b.disabled=true;if(i===q.c)b.classList.add('correct');if(i===choice&&i!==q.c)b.classList.add('wrong')});if(choice===q.c)score+=100;const good=choice===q.c;document.querySelector('#feedback').innerHTML=`<div class="explanation"><b>${good?'✓ RESPUESTA CORRECTA':'↳ REVISÁ ESTE CONCEPTO'}</b><p>${q.e}</p></div><button class="primary next" id="next">${index===active.length-1?'Ver resultado':'Siguiente pregunta →'}</button>`;document.querySelector('#next').onclick=next;updateProgress()}
function next(){index++;if(index>=active.length){panel.innerHTML=`<div class="empty-state"><div class="terminal-icon">✓</div><h3>Sesión completada</h3><p>Obtuviste <b>${score}</b> puntos de ${active.length*100}. Repetí la ruta para consolidar los conceptos o elegí un módulo distinto.</p><button class="primary" onclick="start(currentRoute)">Repetir simulación</button></div>`;index=active.length;updateProgress();return}render()}
function updateProgress(){const total=active.length||1,pct=(index+(answered?1:0))/total*100;document.querySelector('#progressBar').style.width=pct+'%';document.querySelector('#progressText').textContent=active.length?`${Math.min(index+1,total)} / ${total} PREGUNTAS`:'LISTO PARA EMPEZAR';document.querySelector('#scoreText').textContent=score+' PTS'}
